/* Lead Status Rule */
IF(
    ISPICKVAL(Status, "Closed - Not Converted"),
    0,

    /* Otherwise evaluate all criteria normally */
    (
        /* Do Not Call */
        IF(DoNotCall = TRUE, -25, 0) +

        /* Email populated */
        IF(NOT(ISBLANK(Email)), 15, 0) +

        /* Lead Source scoring */
        IF(
            ISPICKVAL(LeadSource, "Web"), 20,
            IF(
                ISPICKVAL(LeadSource, "Phone Inquiry"), 35,
                IF(
                    ISPICKVAL(LeadSource, "Partner Referral"), 25,
                    IF(
                        ISPICKVAL(LeadSource, "Purchased List"), 10,
                        0   /* All other lead sources */
                    )
                )
            )
        )
    )
)

/* 0 Star: Score < 10 */
IF(
    Lead_Score__c < 10,
    '<img src="/img/samples/stars_000.gif" alt="0 Star" title="0 Star"/>',

/* 1 Star: 10–19 */
IF(
    Lead_Score__c  < 20,
    '<img src="/img/samples/stars_100.gif" alt="1 Star" title="1 Star"/>',

/* 2 Stars: 20–29 */
IF(
    Lead_Score__c < 30,
    '<img src="/img/samples/stars_200.gif" alt="2 Star" title="2 Star"/>',

/* 3 Stars: 30–39 */
IF(
    Lead_Score__c < 40,
    '<img src="/img/samples/stars_300.gif" alt="3 Star" title="3 Star"/>',

/* 4 Stars: 40–49 */
IF(
    Lead_Score__c < 50,
    '<img src="/img/samples/stars_400.gif" alt="4 Star" title="4 Star"/>',

/* 5 Stars: 50+ */
    '<img src="/img/samples/stars_500.gif" alt="5 Star" title="5 Star"/>'
